import java.lang.reflect.*;
import java.nio.file.*;
import java.util.*;
public class JassCheck {
    static final String A="de.peeeq.wurstscript.jassAst.JassAst";
    static Object call(Object on,String name,Object... args) throws Exception {
        Class<?> owner=on instanceof Class?(Class<?>)on:on.getClass();
        for(Method m:owner.getMethods()) {
            if(!m.getName().equals(name))continue;
            Class<?>[] types=m.getParameterTypes();
            if(!m.isVarArgs() && types.length==args.length) {
                boolean ok=true;
                for(int i=0;i<types.length;i++)if(!compatible(types[i],args[i]))ok=false;
                if(ok){m.setAccessible(true);return m.invoke(on instanceof Class?null:on,args);}
            }
            if(m.isVarArgs() && types.length==1) {
                Class<?> component=types[0].getComponentType();
                Object arr=Array.newInstance(component,args.length);
                boolean ok=true;
                for(int i=0;i<args.length;i++)if(compatible(component,args[i]))Array.set(arr,i,args[i]);else ok=false;
                if(ok){m.setAccessible(true);return m.invoke(on instanceof Class?null:on,arr);}
            }
        }
        throw new NoSuchMethodException(owner+" "+name+" "+Arrays.toString(args));
    }
    static boolean compatible(Class<?> type,Object arg) {
        return arg==null?!type.isPrimitive():type.isInstance(arg)||(type==boolean.class&&arg instanceof Boolean)||(type==int.class&&arg instanceof Integer);
    }
    static Object ast(String name,Object... args) throws Exception{return call(Class.forName(A),name,args);}
    static Object make(String name,Object... args)throws Exception{
        for(Constructor<?> m:Class.forName(name).getConstructors()){
            Class<?>[] t=m.getParameterTypes();
            if(t.length!=args.length)continue;
            boolean ok=true;
            for(int i=0;i<t.length;i++)if(!compatible(t[i],args[i]))ok=false;
            if(ok)return m.newInstance(args);
        }
        throw new NoSuchMethodException(name);
    }
    static List<Object> nodes(Object root,String kind)throws Exception{
        List<Object> found=new ArrayList<>();
        if(root.getClass().getSimpleName().equals(kind+"Context"))found.add(root);
        int children=(Integer)call(root,"getChildCount");
        for(int i=0;i<children;i++)found.addAll(nodesAt(root,i,kind));
        return found;
    }
    static List<Object> nodesAt(Object root,int n,String kind)throws Exception{
        Method m=root.getClass().getMethod("getChild",int.class);m.setAccessible(true);
        return nodes(m.invoke(root,n),kind);
    }
    static Object only(Object root,String kind)throws Exception{
        List<Object> found=nodes(root,kind);
        if(found.size()!=1)throw new IllegalArgumentException(kind+" count "+found.size());
        return found.get(0);
    }
    static Object fn(String name,Object params,String result,Object... body)throws Exception{
        return ast("JassFunction",name,params,result,ast("JassVars"),ast("JassStatements",body),false);
    }
    public static void main(String[] args)throws Exception {
        String source=Files.readString(Path.of("hello.j"));
        Object stream=call(Class.forName("org.antlr.v4.runtime.CharStreams"),"fromString",source);
        Object lexer=make("de.peeeq.wurstscript.antlr.JassLexer",stream);
        Object tokens=make("org.antlr.v4.runtime.CommonTokenStream",lexer);
        Object parser=make("de.peeeq.wurstscript.antlr.JassParser",tokens);
        Object parsed=call(parser,"compilationUnit");
        if(!Integer.valueOf(0).equals(call(parser,"getNumberOfSyntaxErrors")))throw new IllegalArgumentException("JASS syntax error");
        Object function=only(parsed,"JassFuncDef");
        Object signature=only(function,"JassFuncSignature");
        String functionName=call(call(signature,"ID"),"getText").toString();
        Object sourceCall=only(function,"ExprFunctionCall");
        String callName=call(call(sourceCall,"ID"),"getText").toString();
        Object argument=only(sourceCall,"JassExprPrimary");
        String literal=call(call(argument,"STRING"),"getText").toString();
        if(!literal.startsWith("\"")||!literal.endsWith("\""))throw new IllegalArgumentException(literal);
        Object originalCall=ast("JassStmtCall",callName,ast("JassExprlist",ast("JassExprStringVal",literal.substring(1,literal.length()-1))));
        Object originalFunction=fn(functionName,ast("JassSimpleVars"),"nothing",originalCall);
        Object captured=ast("JassSimpleVar","string","corpusCaptured");
        Object binding=fn("BJDebugMsg",ast("JassSimpleVars",ast("JassSimpleVar","string","msg")),"nothing",
            ast("JassStmtSet","corpusCaptured",ast("JassExprVarAccess","msg")));
        Object readback=fn("corpusReadback",ast("JassSimpleVars"),"string",
            ast("JassStmtReturn",ast("JassExprVarAccess","corpusCaptured")));
        Object program=ast("JassProg",ast("JassTypeDefs"),ast("JassVars",captured),ast("JassNatives"),
            ast("JassFunctions",originalFunction,binding,readback));
        Object machine=make("de.peeeq.wurstio.jassinterpreter.JassInterpreter");
        call(machine,"loadProgram",program);
        Class<?> il=Class.forName("de.peeeq.wurstscript.intermediatelang.ILconst");
        Object empty=Array.newInstance(il,0);
        Method eval=machine.getClass().getMethod("executeFunction",String.class,empty.getClass());
        eval.invoke(machine,functionName,empty);
        Object value=eval.invoke(machine,"corpusReadback",empty);
        System.out.println(call(value,"getVal"));
    }
}
